import type { ActionPromptDraft } from '../../../../services/actions/action_prompt_draft_service'
import { dataService } from '../../../../services/data/data_service'
import { dialogService } from '../../../../services/dialog_service'
import { useClaudeRateLimits } from '../../../hooks/use_claude_rate_limits'
import { useCodexRateLimits } from '../../../hooks/use_codex_rate_limits'
import { useProjectConfig } from '../../../hooks/use_project_config'
import { defaultScheduleAction } from '../popup/action_popup_defaults'
import type { ActionScheduleStore } from './action_schedule_store'
import { ActionScheduleForm, type ActionScheduleFormChange } from './action_schedule_form'
import { accountTrackerOptions, cardScheduleOptions, scheduleTargetStates } from './action_schedule_options'
import { canRegisterSchedule, createScheduleTrigger, type ActionScheduleTriggerSources } from './action_schedule_trigger'

const EMPTY_CARDS: ProjectSnapshot['activeCards'] = []
const SCHEDULE_POPOVER_ELEVATION = 8
const SCHEDULE_POPOVER_WIDTH = 360

function subscribeActiveCards(listener: () => void) {
    dataService.addEventListener('changed', listener)

    return () => dataService.removeEventListener('changed', listener)
}

function getActiveCards() {
    return dataService.getState().snapshot?.activeCards ?? EMPTY_CARDS
}

interface ActionScheduleOwnerProps {
    action: ActionDefinition
    context: ActionContext
    promptDraft: ActionPromptDraft
    store: ActionScheduleStore
}

/** Binds service-owned schedule form state to loaded runtime and project data. */
export function ActionScheduleOwner({ action, context, promptDraft, store }: ActionScheduleOwnerProps) {
    const snapshot = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const activeCards = useSyncExternalStore(subscribeActiveCards, getActiveCards, getActiveCards)
    const claudeState = useClaudeRateLimits()
    const codexState = useCodexRateLimits()
    const projectConfig = useProjectConfig()
    if (!snapshot.open) return null

    const sources: ActionScheduleTriggerSources = {
        accountTrackers: accountTrackerOptions(claudeState, codexState),
        cards: cardScheduleOptions(activeCards, context.cardInternalId),
        targetStates: scheduleTargetStates(projectConfig?.states),
    }
    const handleChange = (change: ActionScheduleFormChange) => {
        if (change.type === 'trigger-type') store.setTriggerType(change.triggerType)
        else if (change.type === 'timestamp') store.setTimestamp(change.timestamp)
        else if (change.type === 'agent') store.setAgent(change.agent)
        else if (change.type === 'tracker') store.setAccountTracker(change.limitId, change.windowId)
        else if (change.type === 'card') store.setCardInternalId(change.cardInternalId)
        else store.setTargetState(change.targetState)
    }
    const handleRegister = async () => {
        store.setMessage(null)
        try {
            promptDraft.requestFlush()
            const prompt = promptDraft.getSnapshot()
            const trigger = createScheduleTrigger(store.getSnapshot(), sources)
            await defaultScheduleAction(action, context, trigger, prompt)
            store.close()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not register schedule' })
        }
    }
    const handleClose = () => store.close()

    return (
        <Popover
            anchorEl={snapshot.anchorElement}
            anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
            onClose={handleClose}
            open={snapshot.open}
            slotProps={{
                paper: {
                    'aria-label': 'Schedule action',
                    elevation: SCHEDULE_POPOVER_ELEVATION,
                    role: 'dialog',
                    sx: {
                        bgcolor: 'background.paper', border: '1px solid', borderColor: 'divider',
                        maxWidth: (theme) => `calc(100vw - ${theme.spacing(4)})`, p: 2, width: SCHEDULE_POPOVER_WIDTH,
                    },
                },
            }}
            transformOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        >
            <ActionScheduleForm
                accountTrackers={sources.accountTrackers}
                canRegister={canRegisterSchedule(snapshot, sources)}
                cards={sources.cards}
                message={snapshot.message}
                onChange={handleChange}
                onRegister={handleRegister}
                snapshot={snapshot}
                targetStates={sources.targetStates}
            />
        </Popover>
    )
}

export type ActionScheduleTriggerType = 'account-reset' | 'at' | 'card-state'

interface ActionScheduleSnapshotBase {
    message: string | null
    open: boolean
    triggerType: ActionScheduleTriggerType
}

export interface AtActionScheduleSnapshot extends ActionScheduleSnapshotBase {
    timestamp: string
    triggerType: 'at'
}

export interface AccountResetActionScheduleSnapshot extends ActionScheduleSnapshotBase {
    agent: string
    limitId: string
    triggerType: 'account-reset'
    windowId: string
}

export interface CardStateActionScheduleSnapshot extends ActionScheduleSnapshotBase {
    cardInternalId: string
    targetState: string
    triggerType: 'card-state'
}

export type ActionScheduleSnapshot =
    | AccountResetActionScheduleSnapshot
    | AtActionScheduleSnapshot
    | CardStateActionScheduleSnapshot

export type ActionScheduleStoreSnapshot = ActionScheduleSnapshot & { anchorElement: HTMLElement | null }

interface AccountResetDraft {
    agent: string
    limitId: string
    windowId: string
}

interface CardStateDraft {
    cardInternalId: string
    targetState: string
}

const INITIAL_SNAPSHOT: ActionScheduleStoreSnapshot = {
    anchorElement: null,
    message: null,
    open: false,
    timestamp: '',
    triggerType: 'at',
}

/** Owns trigger-specific schedule form state at schedule-section boundary. */
export class ActionScheduleStore extends EventTarget {
    private readonly accountResetDraft: AccountResetDraft = { agent: '', limitId: '', windowId: '' }
    private readonly cardStateDraft: CardStateDraft = { cardInternalId: '', targetState: '' }
    private snapshot: ActionScheduleStoreSnapshot = INITIAL_SNAPSHOT
    private timestamp = ''

    readonly getSnapshot = () => this.snapshot
    readonly getOpenSnapshot = () => this.snapshot.open

    readonly subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener)

        return () => this.removeEventListener('changed', listener)
    }

    toggle(anchorElement: HTMLElement) {
        if (this.snapshot.open) {
            this.close()
            return
        }

        this.publish({ ...this.snapshot, anchorElement, message: null, open: true })
    }

    close() {
        const { anchorElement, message, open } = this.snapshot
        if (!open && anchorElement === null && message === null) return

        this.publish({ ...this.snapshot, anchorElement: null, message: null, open: false })
    }

    setTriggerType(triggerType: ActionScheduleTriggerType) {
        if (triggerType === this.snapshot.triggerType) return

        const common = { anchorElement: this.snapshot.anchorElement, message: null, open: this.snapshot.open }
        if (triggerType === 'at') {
            this.publish({ ...common, timestamp: this.timestamp, triggerType })
            return
        }
        if (triggerType === 'account-reset') {
            this.publish({ ...common, ...this.accountResetDraft, triggerType })
            return
        }

        this.publish({ ...common, ...this.cardStateDraft, triggerType })
    }

    setTimestamp(timestamp: string) {
        this.timestamp = timestamp
        if (this.snapshot.triggerType === 'at') this.publish({ ...this.snapshot, message: null, timestamp })
    }

    setAgent(agent: string) {
        this.accountResetDraft.agent = agent
        this.accountResetDraft.limitId = ''
        this.accountResetDraft.windowId = ''
        if (this.snapshot.triggerType === 'account-reset') {
            this.publish({ ...this.snapshot, ...this.accountResetDraft, message: null })
        }
    }

    setAccountTracker(limitId: string, windowId: string) {
        this.accountResetDraft.limitId = limitId
        this.accountResetDraft.windowId = windowId
        if (this.snapshot.triggerType === 'account-reset') {
            this.publish({ ...this.snapshot, ...this.accountResetDraft, message: null })
        }
    }

    setCardInternalId(cardInternalId: string) {
        this.cardStateDraft.cardInternalId = cardInternalId
        if (this.snapshot.triggerType === 'card-state') {
            this.publish({ ...this.snapshot, cardInternalId, message: null })
        }
    }

    setTargetState(targetState: string) {
        this.cardStateDraft.targetState = targetState
        if (this.snapshot.triggerType === 'card-state') {
            this.publish({ ...this.snapshot, message: null, targetState })
        }
    }

    setMessage(message: string | null) {
        this.publish({ ...this.snapshot, message })
    }

    private publish(snapshot: ActionScheduleStoreSnapshot) {
        this.snapshot = snapshot
        this.dispatchEvent(new Event('changed'))
    }
}

