    const bridge = getElectronActionBridge()
    if (!bridge?.registerActionSchedule) throw new Error('Scheduling actions requires Electron local mode')
    if (action.id === CUSTOM_PROMPT_ACTION_ID && prompt.trim().length === 0) {
